```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational assessment", "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in other topics." .

ea:TestItem a owl:Class ;
  skos:altLabel "item", "question" ;
  rdfs:comment "A single stimulus (stem/prompt) within a test to which a test taker responds. 'Item' is preferred over 'question' because not all items are phrased as questions." .

ea:isItemOf a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:hasItem a owl:ObjectProperty ;
  owl:inverseOf ea:isItemOf ;
  rdfs:domain ea:Test ; rdfs:range ea:TestItem .

#################################################################
# AXIS: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  rdfs:comment "The level on which assessment can focus: individual learner, learning community, course, program, institution, or educational system." .

ea:IndividualLearnerLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:IndividualLearnerLevel ea:LearningCommunityLevel ea:CourseLevel
    ea:AcademicProgramLevel ea:InstitutionLevel ea:EducationalSystemLevel ) .

#################################################################
# AXIS 1: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  rdfs:comment "Value-partition axis for the placement/formative/summative/diagnostic categorization given as coordinate alternatives in one passage." .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  rdfs:comment "Used to place students according to prior achievement, level of knowledge, or personal characteristics at an appropriate point in instruction. Generally ungraded." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation", "formative feedback" ;
  rdfs:comment "Conducted during the learning process to modify teaching and learning activities; typically ungraded, in-process feedback." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  rdfs:comment "Carried out at the end of a course or project to evaluate learning against a standard; typically graded." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a fourth coordinate category alongside placement, formative, and summative assessment (making it disjoint from FormativeAssessment via PurposeCategory); another passage states 'a common form of formative assessment is diagnostic assessment', making DiagnosticAssessment a subclass of FormativeAssessment. Both claims are encoded, even though jointly they are logically inconsistent with the disjoint union below." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

#################################################################
# PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Similar to summative assessment in focusing on achievement; a well-defined task requires students to create, produce, or do something, often with real-world application, scored by human scorers against a standard." .

ea:hasOutputFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceOutputFormatCategory .

ea:PerformanceOutputFormatCategory a owl:Class ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:ProductOutputFormat a owl:Class ; rdfs:subClassOf ea:PerformanceOutputFormatCategory .
ea:PerformanceOutputFormat a owl:Class ; rdfs:subClassOf ea:PerformanceOutputFormatCategory .

ea:PerformanceOutputFormatCategory owl:disjointUnionOf
  ( ea:ProductOutputFormat ea:PerformanceOutputFormat ) .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  skos:altLabel "performance assessment" ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting." .

#################################################################
# AXIS 2: OBJECTIVE / SUBJECTIVE (applies to Assessment and TestItem)
#################################################################

ea:ResponseTypeCategory a owl:Class .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:ResponseTypeCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it." .

ea:hasItemResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TestItem ; rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasItemResponseType ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasItemResponseType ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "Contrasts with multiple-choice items: more than one answer may be keyed as correct." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "essay question", "free response question", "FRQ" .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists true/false as a coordinate, disjoint objective item type alongside multiple-choice; another passage states there are 'two families of multiple-choice questions', the first being the True/False family, making TrueFalseItem a subclass of MultipleChoiceItem. Both claims are encoded." .

ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Second family of multiple-choice items; requires choosing only one answer from a list." .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:Stem a owl:Class ; rdfs:comment "The opening of an item: a problem, question, or incomplete statement." .
ea:Option a owl:Class ; rdfs:comment "A possible answer offered in a multiple-choice item." .
ea:Key a owl:Class ; rdfs:subClassOf ea:Option .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:Option .
ea:Key owl:disjointWith ea:Distractor .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Stem .
ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Option .
ea:hasKey a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key ;
  rdfs:comment "Only one answer may be keyed as correct in a multiple-choice item." .

#################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria, regardless of other examinees' performance." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  skos:altLabel "normative assessment", "grading on the curve" .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] ;
  skos:altLabel "ipsative measure" ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:NormReferencedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:NormReferencedAssessment ) ] ;
  skos:altLabel "NRT" ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:CriterionReferencedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:CriterionReferencedAssessment ) ] ;
  skos:altLabel "CRT" ;
  rdfs:comment "Uses test scores to show how well test takers performed on a given task, not how they performed compared to others." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal ;
  rdfs:comment "The minimum score required to pass a mastery test; the criterion itself is the subject-matter domain, not the cutscore." .

#################################################################
# AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a final grade; may include observation, checklists, rubrics, portfolios." .

#################################################################
# AXIS 5: LOCUS (internal / external)
#################################################################

ea:LocusCategory a owl:Class .
ea:InternalCategory a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalCategory a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalCategory ea:ExternalCategory ) .

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalCategory ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalCategory ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# AXIS 6: STANDARDIZATION (Test-level)
#################################################################

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf
  ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent, standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

#################################################################
# AXIS 7: STAKES (Test-level)
#################################################################

ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance; important decisions depend on the result." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ]
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked by grade/percentile and top rankers are selected." .

#################################################################
# OTHER TEST / ASSESSMENT SUBCLASSES
#################################################################

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Administered on paper or on a computer." .

ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Test, ea:PerformanceBasedAssessment ;
  skos:altLabel "work sample" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .

ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment." .

ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A final review and assessment of each student's knowledge at the end of a course." .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low-value and formative." .

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates progress periodically between formative and summative assessments; some educators consider interim assessments formative, others summative - the corpus notes ongoing debate about this distinction." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Determines whether students may need specialized assistance or are ready to begin a course, grade level, or program." .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used across a school or district with shared format/scoring to ensure consistent evaluation among teachers." .

ea:PortfolioBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "student portfolio", "e-portfolio", "digital portfolio" ;
  rdfs:comment "A compilation of academic work assembled to evaluate learning progress and achievement over time." .

ea:ComplexAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires a rubric and an expert examiner; example items include theses and funding proposals." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course, often including formative assessment; used as an alternative to final examinations." .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure. Reliability does not imply validity, but a valid measure must necessarily be reliable; a test that is not reliable cannot be valid." .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

ea:hasValidityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Validity ; rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" ;
  rdfs:comment "Systematic examination of test content to determine whether it covers a representative sample of the behavior domain to be measured." .

ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "The extent to which an operationalization correlates with or predicts a theoretically related outcome (the criterion)." .

ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "TENSION: one passage lists construct validity as a coordinate category of validity evidence alongside content, criterion, consequential, and face validity (hence included in the disjoint union below); another passage states construct validity 'subsumes all other types of validity' and is 'not distinct from support for the substantive theory', i.e. the overarching/superordinate concern of validity. Both claims are encoded." .

ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "An estimate of whether a test appears, on its face, to measure what it purports to measure; does not guarantee actual measurement." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                ea:ConsequentialValidity ea:FaceValidity ) .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data and criterion data are collected at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data are collected first to predict criterion data collected at a later time." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Degree to which two measures of theoretically related constructs are in fact related." .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  skos:altLabel "divergent validity" ;
  rdfs:comment "Degree to which concepts or measures that are supposed to be unrelated are, in fact, unrelated." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment; the freedom of a measure from measurement error. The corpus gives two independent classification axes for reliability: (1) by source of error ('four types of reliability'), and (2) by estimation method ('several general classes of reliability estimates'). Both are encoded as (non-exhaustive, separately disjoint) subclass groups of Reliability." .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

# (1) classification by source of error
ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Includes personal problems, sickness, or fatigue of the student." .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Includes rater bias and subjectivity." .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Concerns the conditions of the test-taking process." .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Related to the nature of the test itself." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

# (2) classification by estimation method
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "inter-rater agreement", "inter-observer reliability" ;
  rdfs:comment "Degree of agreement between two or more raters in their appraisals." .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one test administration to the next, using the same rater/instrument and conditions." .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree to which test scores are consistent when there is variation in the methods or instruments used." .

ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Inter-method reliability when dealing with alternate forms of a test." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
